import{_ as a,o as t,c as r,ak as o}from"./chunks/framework.B8jO0odJ.js";const p=JSON.parse('{"title":"Team board: quick guide","description":"Open the Chainy board. Sign in with your individual username (sherwin, christian, luis, sean, or miguel). The temporary first-use password is 123. Change it to your own privat","frontmatter":{"title":"Team board: quick guide","description":"Open the Chainy board. Sign in with your individual username (sherwin, christian, luis, sean, or miguel). The temporary first-use password is 123. Change it to your own privat","source":"docs/team-board-guide.md","category":"Other documents","sourceUpdated":"2026-10-13T02:10:44+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/team-board-guide.md","filePath":"content/docs/team-board-guide.md"}'),i={name:"content/docs/team-board-guide.md"};function n(s,e,d,h,c,l){return t(),r("div",null,[...e[0]||(e[0]=[o('<div><h1 id="team-board-quick-guide">Team board: quick guide<a class="header-anchor" href="#team-board-quick-guide" aria-label="Link to this section">​</a></h1><p>Open the <a href="https://owenlim225.github.io/Chainy-Docs/board/">Chainy board</a>. Sign in with your individual username (<code>sherwin</code>, <code>christian</code>, <code>luis</code>, <code>sean</code>, or <code>miguel</code>). The temporary first-use password is <strong>123</strong>. Change it to your own private password when prompted, before using the board; this lets the history identify the teammate who made each change. The board is for project tasks only and is separate from learners&#39; offline game profiles.</p><h2 id="update-a-card">Update a card<a class="header-anchor" href="#update-a-card" aria-label="Link to this section">​</a></h2><ul><li>Use the Board view for cards or Timeline for the Gantt schedule. The colors identify work lanes; the card name and owner show what the task is about. Card names describe the work rather than relying on task codes.</li><li>Select a card to open it; use its separate move grip when you want to drag it. In a card, add checklist steps, tick them off, or remove them as the work changes. You can read the full description, completion check, dates, prerequisites, history, evidence and reference links. Fields grow with their contents; the page can scroll when a long card needs more space.</li><li>Move the card when work starts, is ready for review, or is finished. Mark it Done only when the card&#39;s check is met.</li><li>Use <strong>Evidence and updates</strong> for what changed, what remains, and any blocker. Put each shareable source, build, image, or review URL in <strong>Reference links</strong> on its own <code>https://</code> line. Those links also go to the public GitHub issue copy, so never paste a signed/private link, login token, learner name, or participant record. Save the card to add the links to its history and linked GitHub record.</li><li>Each card has one role lane and one owner. If someone in a different role needs to continue the work, create a separate card with a clear handoff instead of adding a second owner.</li></ul><h2 id="archive-and-history">Archive and history<a class="header-anchor" href="#archive-and-history" aria-label="Link to this section">​</a></h2><p>Choose <strong>Archive task</strong> when work should leave the active board. Archiving hides it from the working board and timeline but keeps its record and history available in <strong>Archive</strong>. Restore it if needed. Cards are not permanently deleted.</p><p>The History tab records the account that changed a card, the change, the board area, and the server time. Change your initial shared password immediately so the person recorded in history is meaningful. Do not put learner names or participant records in board cards; use synthetic or approved anonymous evidence.</p><p>Trello is retired. Make changes in this board; the linked GitHub issue is an automatically updated copy. See <a href="/Chainy-Docs/content/docs/team-delegation.html">role ownership</a>, <a href="/Chainy-Docs/content/docs/kanban-plan-draft.html">task plan</a>, and <a href="/Chainy-Docs/content/docs/project-baseline.html">project baseline</a>.</p></div>',1)])])}const m=a(i,[["render",n]]);export{p as __pageData,m as default};
